def calibrate(d):
    c = d['calibration_load_cells']
    x = c['true_channel_loads']
    y = c['bridge_raw']
    b = np.linalg.lstsq(np.c_[x, np.ones(len(x))], y, rcond=None)[0]
    return (np.linalg.solve(b[:4], np.ones(4)), b[4])

def prep(s, stats=None, imp=None):
    lab = s['lab_id']
    stratum = s['stratum']
    ref = s['ref_coupons']
    raw = s['coupon_features_raw']
    if stats is None:
        stats = {i: (np.median(ref[lab == i].mean(0)), np.median(ref[lab == i].std(0))) for i in np.unique(lab)}
    x = raw.copy()
    for i in np.unique(lab):
        z = ref[lab == i]
        (m, v) = stats.get(i, (np.median(z.mean(0)), np.median(z.std(0))))
        x[lab == i] = (x[lab == i] - m) / max(v, 1e-08)
    if imp is None:
        (_, iv, cnt) = np.unique(np.c_[lab, stratum], axis=0, return_inverse=True, return_counts=True)
        w = 1 / cnt[iv]
        imp = np.nansum(x * w[:, None], axis=0) / np.sum(np.isfinite(x) * w[:, None], axis=0)
    return (np.where(np.isfinite(x), x, imp), stats, imp)

def basis(tau, dt, t, u, h, x, kind):
    dt = np.asarray(dt)
    tail = np.cumsum(dt[::-1])[::-1] - dt
    g = -np.expm1(-dt[:, None] / tau) * np.exp(-tail[:, None] / tau)
    m = u @ g
    if kind.startswith('free'):
        m = np.concatenate([np.broadcast_to(h[:, None], m.shape), m], axis=1)
        tau = np.tile(tau, 2)
    elif kind.startswith('hold'):
        m = h[:, None] + m * 0
    elif kind.startswith('plus'):
        m = h[:, None] + m
    elif kind.startswith('reverse'):
        m = h[:, None] - u[:, ::-1] @ g
    elif kind.startswith('steps'):
        m = h[:, None] - u @ np.exp(-tail[:, None] / tau)
    elif kind.startswith('hist'):
        pass
    else:
        m = h[:, None] - m
    f = m[:, None, :] * -np.expm1(-t[:, None] / tau)
    r = m / tau
    if '_rate' in kind:
        f = f * tau
        r = r * tau
    z = np.c_[np.ones(len(x)), x]
    if '_stress' in kind:
        z = z * h[:, None]
    return (np.concatenate([f, z[:, None, :] * t[None, :, None]], axis=-1), np.c_[r, z])
